import re

pk = [int(l) for l in open('/home/ctfplayer/ctf_files/files/pubkey.txt') if l.strip() and not l.startswith('#')]
cts = [int(l) for l in open('/home/ctfplayer/ctf_files/files/ciphertext.txt') if l.strip() and not l.startswith('#')]
n = len(pk)

def check(bits, a, s):
    return bits is not None and sum(bits[i]*a[i] for i in range(len(a))) == s

def solve_knapsack(a, s, N=None, tries=6):
    n = len(a)
    if N is None:
        N = max(a)
    # standard CJLOSS lattice
    for mult in [1, 2, 4]:
        M = Matrix(ZZ, n+1, n+1)
        for i in range(n):
            M[i, i] = mult*2
            M[i, n] = mult*a[i]
        for j in range(n):
            M[n, j] = 1
        M[n, n] = mult*s
        for bs in [0, 20, 30, 40]:
            try:
                if bs == 0:
                    B = M.LLL()
                else:
                    B = M.BKZ(block_size=bs)
            except Exception as e:
                continue
            for row in B:
                if row[n] == 0 and all(abs(row[j]) == 1 for j in range(n)):
                    bits = [1 if row[j] == -1 else 0 for j in range(n)]
                    if check(bits, a, s):
                        return bits
    return None

flag = b""
for idx, s in enumerate(cts):
    bits = solve_knapsack(pk, s)
    if bits is None:
        print("block", idx, "FAILED")
        flag += b"?????????"
        continue
    block = bytearray()
    for b in range(9):
        v = 0
        for k in range(8):
            v = (v << 1) | bits[b*8 + k]
        block.append(v)
    print(idx, bytes(block))
    flag += bytes(block)

print("FLAG:", flag)

