n = len(pk)
s = cts[3]
print("target", s)

def build(a, s, N):
    n = len(a)
    M = Matrix(ZZ, n+1, n+1)
    for i in range(n):
        M[i, i] = 2
        M[i, n] = N*a[i]
    for j in range(n):
        M[n, j] = 1
    M[n, n] = N*s
    return M

def extract(row, a, s):
    if row[n] != 0:
        return None
    if not all(abs(row[j]) == 1 for j in range(n)):
        return None
    bits = [1 if row[j] == -1 else 0 for j in range(n)]
    if sum(bits[i]*a[i] for i in range(n)) == s:
        return bits
    return None

found = None
