        M = build(pk, s, N)
        try:
            B = M.LLL() if bs == 0 else M.BKZ(block_size=bs)
        except Exception as e:
            continue
        for row in B:
            r = extract(row, pk, s)
            if r is not None:
                found = r
                print("FOUND N=", N, "bs=", bs)
